// Generated by tools/hoenn/gen_hoenn_base_spots.py from data/hoenn/base_spots.json.
// Secret bases at Hoenn's reopened legendary sites (2.0 parts 12 and 12b).
// An ID is group * 10 + variant; Emerald's own spots use variants 1-4 of groups 0-23.
// Included by constants/secret_bases.h before NUM_SECRET_BASE_GROUPS.
#ifndef GUARD_CONSTANTS_HOENN_SECRET_BASES_H
#define GUARD_CONSTANTS_HOENN_SECRET_BASES_H

// Chamber bases: new groups after SECRET_BASE_SHRUB4.
#define SECRET_BASE_HOENN_GROUP_SKY_PILLAR_1 241
#define SECRET_BASE_HOENN_GROUP_SKY_PILLAR SECRET_BASE_GROUP(24)
#define SECRET_BASE_HOENN_GROUP_SEALED_CHAMBER_1 251
#define SECRET_BASE_HOENN_GROUP_SEALED_CHAMBER SECRET_BASE_GROUP(25)
#define HOENN_SECRET_BASE_GROUP_COUNT 2

// Rows for sSecretBaseEntrancePositions (map number, warp, PC x, PC y).
#define HOENN_SECRET_BASE_ENTRANCE_POSITIONS \
    [SECRET_BASE_HOENN_GROUP_SKY_PILLAR] = MAP_NUM(MAP_SECRET_BASE_SKY_PILLAR_HOENN), 0, 5, 9, \
    [SECRET_BASE_HOENN_GROUP_SEALED_CHAMBER] = MAP_NUM(MAP_SECRET_BASE_SEALED_CHAMBER_HOENN), 0, 1, 2, \

// TRUE for a chamber base's map number (in the secret base map group).
#define HOENN_IS_CHAMBER_BASE_MAP_NUM(mapNum) ((mapNum) == MAP_NUM(MAP_SECRET_BASE_SKY_PILLAR_HOENN) || (mapNum) == MAP_NUM(MAP_SECRET_BASE_SEALED_CHAMBER_HOENN))

// Entrance spots.
#define SECRET_BASE_HOENN_DESERT_RUINS 9  // RED_CAVE1, variant 9: DesertRuins (8,2)
#define SECRET_BASE_HOENN_ISLAND_CAVE 89  // BLUE_CAVE1, variant 9: IslandCave (8,2)
#define SECRET_BASE_HOENN_ANCIENT_TOMB 129  // YELLOW_CAVE1, variant 9: AncientTomb (8,2)
#define SECRET_BASE_HOENN_CAVE_OF_ORIGIN 99  // BLUE_CAVE2, variant 9: CaveOfOrigin_B1F (7,12)
#define SECRET_BASE_HOENN_SEAFLOOR_CAVERN 109  // BLUE_CAVE3, variant 9: SeafloorCavern_Room9 (13,40)
#define SECRET_BASE_HOENN_SKY_PILLAR 241  // HOENN_SKY_PILLAR, variant 1: SkyPillar_Top (12,14)
#define SECRET_BASE_HOENN_SEALED_CHAMBER 251  // HOENN_SEALED_CHAMBER, variant 1: SealedChamber_InnerRoom (5,2)

// TRUE for a base at one of the sites.
#define HOENN_IS_SITE_BASE(id) ((id) == SECRET_BASE_HOENN_DESERT_RUINS \
                             || (id) == SECRET_BASE_HOENN_ISLAND_CAVE \
                             || (id) == SECRET_BASE_HOENN_ANCIENT_TOMB \
                             || (id) == SECRET_BASE_HOENN_CAVE_OF_ORIGIN \
                             || (id) == SECRET_BASE_HOENN_SEAFLOOR_CAVERN \
                             || (id) == SECRET_BASE_HOENN_SKY_PILLAR \
                             || (id) == SECRET_BASE_HOENN_SEALED_CHAMBER)

#endif
